//! CSS Typed OM (`typed_om.js`): the property registry measured from Chrome 156 and the
//! native property-value grammar check the reifier shares with CSSStyleDeclaration.
use super::*;
use cssparser::{Parser, ParserInput};
use lightningcss::properties::{Property, PropertyId};
use lightningcss::stylesheet::ParserOptions;

/// Blink property metadata and the Chrome 156 registry control, generated by
/// `scripts/typed-om-registry.mjs`.
const REGISTRY: &str = include_str!("typed_om_properties.json");

/// Whether `value` is a valid value of `name` under Lightning CSS's grammar; `None` when
/// Lightning CSS does not model the property.
fn valid_value(name: &str, value: &str) -> Option<bool> {
    let id = PropertyId::from(lightningcss::values::string::CowArcStr::from(
        name.to_string(),
    ));
    if matches!(id, PropertyId::Custom(_)) {
        return None;
    }
    let mut source = ParserInput::new(value);
    let mut input = Parser::new(&mut source);
    let parsed = input.parse_entirely(|input| {
        Property::parse(id, input, &ParserOptions::default())
            .map_err(|_| input.new_custom_error::<(), ()>(()))
    });
    Some(match parsed {
        Ok(Property::Unparsed(_)) | Err(_) => false,
        Ok(_) => true,
    })
}

fn dispatch(
    scope: &mut v8::PinScope,
    args: v8::FunctionCallbackArguments,
    mut rv: v8::ReturnValue,
) {
    let operation = args.get(0).to_rust_string_lossy(scope);
    if operation == "known" {
        let name = args.get(1).to_rust_string_lossy(scope);
        rv.set_bool(valid_value(&name, "").is_some());
        return;
    }
    if operation == "valid" {
        let name = args.get(1).to_rust_string_lossy(scope);
        let value = args.get(2).to_rust_string_lossy(scope);
        match valid_value(&name, &value) {
            Some(valid) => rv.set_bool(valid),
            None => rv.set_null(),
        }
    }
}

pub(super) fn install(scope: &mut v8::PinScope) {
    let global = scope.get_current_context().global(scope);
    bind_method(scope, global, "__typedOmNative", dispatch);
    let registry = v8::String::new(scope, REGISTRY).unwrap();
    set_prop(scope, global, "__typedOmRegistry", registry.into());
    run_js(scope, include_str!("typed_om.js"));
}
